mapper.update:
update mxk_apps_form_based_details
set usernamemapping = #{et.usernameMapping}, passwordmapping = #{et.passwordMapping},
    redirecturi = #{et.redirectUri}, authorizeview = #{et.authorizeView},
    passwordalgorithm = #{et.passwordAlgorithm}, instid = #{et.instId}
where id = #{et.id}

mapper.select:
select *
from mxk_apps_form_based_details fbd,
     mxk_apps app
where app.instId = fbd.instId
  and app.id = #{value}
  and fbd.id = #{value}
  and fbd.id = app.id
  and status = 1
